import React, { useState } from "react";
import youtube2 from "./Assets/social-icons-white-youtube.svg";
import web from "./Assets/facebook.svg";
import { useNavigate } from "react-router-dom";
import "./About.css";
import axios from "axios";

function Header() {
  const navigate = useNavigate();
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  const handleLogout = async () => {
    const token = localStorage.getItem("authToken");
    if (!token) return;

    try {
      await axios.post(`${process.env.REACT_APP_API_BASE_URL}/logout`, {}, {
        headers: { Authorization: `Bearer ${token}` },
      });

      localStorage.clear();
      setIsAuthenticated(false);
      navigate("/");
    } catch (error) {
      navigate("/login");
    }
  };

  return (
    <>
      {/* ======= الهيدر ======= */}
      <header
        style={{
          width: "100%",
          height: "70px",
          background: "#487EEA",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          padding: "0 20px",
          position: "relative",
          zIndex: 1000,
        }}
      >
        <div
          style={{
            fontFamily: "Lemonada",
            fontSize: "1.3rem",
            fontWeight: "bold",
            color: "white",
            textShadow: "2px 2px 4px rgba(0,0,0,0.5)",
          }}
        >
          Mr.Ashraf Abed
        </div>

        {/* زر المينيو (الهامبورجر) */}
        <button
          onClick={() => setMenuOpen(true)}
          style={{
            background: "transparent",
            border: "none",
            color: "white",
            fontSize: "2rem",
            cursor: "pointer",
          }}
        >
          ☰
        </button>
      </header>

      {/* ======= القائمة الجانبية ======= */}
      <div
        style={{
          position: "fixed",
          top: 0,
          right: menuOpen ? 0 : "-260px", // slide in/out
          width: "250px",
          height: "100%",
          background: "rgba(72,126,234,0.95)",
          backdropFilter: "blur(6px)",
          boxShadow: "-2px 0 10px rgba(0,0,0,0.3)",
          transition: "right 0.3s ease-in-out",
          zIndex: 2000,
          display: "flex",
          flexDirection: "column",
          padding: "20px",
          gap: "15px",
        }}
      >
        {/* زر ✕ لقفل المينيو */}
        <button
          onClick={() => setMenuOpen(false)}
          style={{
            alignSelf: "flex-end",
            background: "transparent",
            border: "none",
            fontSize: "2rem",
            color: "#fff",
            cursor: "pointer",
          }}
        >
          ✕
        </button>

        {/* روابط المينيو */}
        <button style={styles.menuButton} onClick={() => { navigate("/"); setMenuOpen(false); }}>
          الرئيسية
        </button>
        <button style={styles.menuButton} onClick={() => { navigate("/about"); setMenuOpen(false); }}>
          عن المنصة
        </button>
        <button style={styles.menuButton} onClick={() => { navigate("/PricingCard"); setMenuOpen(false); }}>
          الحصص الشهرية
        </button>

        {/* زر تسجيل الخروج */}
        <button style={styles.logoutButton} onClick={() => { handleLogout(); setMenuOpen(false); }}>
          تسجيل الخروج
        </button>

        {/* أيقونات السوشيال ميديا */}
        <div
          style={{
            display: "flex",
            gap: "15px",
            marginTop: "auto",
            justifyContent: "center",
          }}
        >
          <a
            href="https://www.facebook.com/AshrafAbed2020/photos"
            target="_blank"
            rel="noopener noreferrer"
          >
            <img src={web} alt="Facebook" style={styles.icon} />
          </a>
          <a
            href="https://www.youtube.com/channel/UC2_e1-9trV5x3beP_wXQfpw"
            target="_blank"
            rel="noopener noreferrer"
          >
            <img src={youtube2} alt="YouTube" style={styles.icon} />
          </a>
        </div>
      </div>
    </>
  );
}

export default Header;

const styles = {
  menuButton: {
    padding: "0.7em 1.5em",
    borderRadius: "25px",
    fontSize: "1.1em",
    cursor: "pointer",
    background: "#fff",
    color: "#487EEA",
    border: "none",
    transition: "all 0.3s ease",
    textAlign: "center",
  },
  logoutButton: {
    padding: "0.7em 1.5em",
    borderRadius: "25px",
    fontSize: "1.1em",
    cursor: "pointer",
    background: "red",
    color: "white",
    border: "none",
    transition: "all 0.3s ease",
    textAlign: "center",
    marginTop: "10px",
  },
  icon: {
    width: "40px",
    height: "40px",
    borderRadius: "6px",
    background: "white",
    padding: "5px",
    boxShadow: "0 2px 5px rgba(0,0,0,0.2)",
  },
};
