import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import FingerprintJS from '@fingerprintjs/fingerprintjs';
import './ProfileCard.css';
import SubscriptionModal from "./SubscriptionModal";
import Footer from './Footer';
import HeaderProfileCard from './HeaderProfileCard';
import Header3 from './Header3';
import Bubbles from '../Bubbles';

const ProfileCard = () => {
  const [lessons, setLessons] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [deviceFingerprint, setDeviceFingerprint] = useState(null);
  const [errorMessages, setErrorMessages] = useState({});
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedLesson, setSelectedLesson] = useState(null);
  const [quizUrl, setQuizUrl] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const fetchLessons = async () => {
      try {
        const educationalLevelId = localStorage.getItem('package_id');
        const authToken = localStorage.getItem('authToken');

        if (!authToken || !educationalLevelId) {
          navigate('/login');
          return;
        }

        const response = await axios.get(
          `${process.env.REACT_APP_API_BASE_URL}/lessons/package/${educationalLevelId}`,
          { headers: { Authorization: `Bearer ${authToken}` } }
        );

        setLessons(response.data);
      } catch (err) {
        setError(err);
        alert("لا يوجد محاضرات متاحة.");
      } finally {
        setLoading(false);
      }
    };

    const fetchDeviceFingerprint = async () => {
      try {
        const fp = await FingerprintJS.load();
        const result = await fp.get();
        setDeviceFingerprint(result.visitorId);
        localStorage.setItem('deviceFingerprint', result.visitorId);
      } catch (err) {
        setErrorMessages(prev => ({ ...prev, global: 'Could not fetch device fingerprint' }));
        navigate('/login');
      }
    };

    const fetchQuizData = async () => {
      try {
        const educationalLevelId = localStorage.getItem('package_id');
        const token = localStorage.getItem('authToken');

        if (!token || !educationalLevelId) return;

        const quizResponse = await fetch(
          `${process.env.REACT_APP_API_BASE_URL}/mcqs/package/${educationalLevelId}`,
          { headers: { Authorization: `Bearer ${token}` } }
        );

        const quizData = await quizResponse.json();
        if (quizData && quizData.mcqs && quizData.mcqs.length > 0) {
          setQuizUrl(quizData.mcqs[0].url);
        }
      } catch (error) {
        console.error("Error fetching quiz data:", error);
      }
    };

    fetchLessons();
    fetchDeviceFingerprint();
    fetchQuizData();
  }, [navigate]);

  const handleSubmit = (lesson) => {
    localStorage.setItem('lesson_id', lesson.id);
    navigate('/Video');
  };

  const [isMobile, setIsMobile] = useState(false);

  const handleResize = () => {
    setIsMobile(window.innerWidth <= 768);
  };

  useEffect(() => {
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <div className="profile-card">
      {isMobile ? <Header3 /> : <HeaderProfileCard />}

      <main className="profile-main">
        <div style={{ width: "100%", height: "100%", position: "absolute" }}>
          <Bubbles />
        </div>

        <section className="lessons-section">
          {loading ? (
            <p>Loading...</p>
          ) : error ? (
            <p className='animiL'>❌❌🔎لا يوجد محاضرات </p>
          ) : (
            Array.isArray(lessons) && lessons.map(lesson => (
              <div
                key={lesson.id}
                style={{
                  background: "rgba(255, 255, 255, 0.1)",
                  backdropFilter: "blur(12px)",
                  borderRadius: "20px",
                  boxShadow: "0 8px 20px rgba(0,0,0,0.25)",
                  overflow: "hidden",
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  transition: "transform 0.3s ease, box-shadow 0.3s ease",
                  padding: "20px",
                  margin: "20px 0",
                  textAlign: "center",
                }}
                onMouseEnter={e => {
                  e.currentTarget.style.transform = "translateY(-8px) scale(1.02)";
                  e.currentTarget.style.boxShadow = "0 12px 30px rgba(0,0,0,0.35)";
                }}
                onMouseLeave={e => {
                  e.currentTarget.style.transform = "translateY(0) scale(1)";
                  e.currentTarget.style.boxShadow = "0 8px 20px rgba(0,0,0,0.25)";
                }}
              >
                <img
                  src={lesson.image.FullSrc}
                  alt="Lesson"
                  style={{
                    width: "100%",
                    height: "220px",
                    objectFit: "cover",
                    borderRadius: "50% / 35%",
                    marginBottom: "15px",
                    border: "3px solid rgba(131, 0, 253, 0.4)",
                  }}
                />
                <h3
                  style={{
                    fontSize: "1.4rem",
                    fontWeight: "600",
                    margin: "10px 0",
                    background: "linear-gradient(45deg, #5e8cea, #a855f7)",
                    WebkitBackgroundClip: "text",
                    WebkitTextFillColor: "transparent",
                  }}
                >
                  {lesson.title}
                </h3>
                <p style={{ fontSize: "0.95rem", color: "#003764ff", marginBottom: "15px" }}>
                  {lesson.description}
                </p>
                <button
                  onClick={() => handleSubmit(lesson)}
                  style={{
                    background: "linear-gradient(45deg, #5e8cea, #a855f7)",
                    border: "none",
                    color: "white",
                    padding: "10px 20px",
                    borderRadius: "50px",
                    cursor: "pointer",
                    fontSize: "1rem",
                    fontWeight: "500",
                    transition: "all 0.3s ease",
                  }}
                  onMouseEnter={e => {
                    e.currentTarget.style.background =
                      "linear-gradient(45deg, #4a6fd1, #9333ea)";
                    e.currentTarget.style.transform = "scale(1.05)";
                  }}
                  onMouseLeave={e => {
                    e.currentTarget.style.background =
                      "linear-gradient(45deg, #5e8cea, #a855f7)";
                    e.currentTarget.style.transform = "scale(1)";
                  }}
                >
                  دخول للمحاضرة
                </button>
              </div>
            ))
          )}

          {isModalOpen && (
            <SubscriptionModal
              lesson={selectedLesson}
              onClose={() => setIsModalOpen(false)}
            />
          )}
        </section>
      </main>

      <div
        className='animiR'
        style={{
          padding: "8px 16px",
          background: '#5E8CEA',
          borderRadius: 7,
          justifyContent: 'center',
          alignItems: 'center',
          display: 'flex'
        }}
      >
        <a
          style={{ color: "white", fontSize: 24, fontFamily: 'Lemonada', textAlign: 'center' }}
          href={quizUrl || "#"}
          onClick={() => {
            if (!quizUrl) alert("لم يتم تنزيل امتحان");
          }}
        >
          الاختبار الشهري
        </a>
      </div>

      <Footer />
    </div>
  );
};

export default ProfileCard;
