import React, { useState } from "react";
import youtube2 from "./Assets/social-icons-white-youtube.svg";
import web from "./Assets/facebook.svg";
import { useNavigate } from "react-router-dom";
import "./About.css";

function Header() {
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false);

  const handleCreateAccount = () => navigate("/signup");

  const handleLogin = () => {
    const token = localStorage.getItem("authToken");
    if (token) {
      navigate("/pricingCard");
    } else {
      navigate("/Login");
    }
  };

  const scrollToSection = (id) => {
    const section = document.getElementById(id);
    if (section) {
      section.scrollIntoView({ behavior: "smooth" });
    }
  };

  return (
    <>
      {/* ======= الهيدر الأساسي ======= */}
      <header
        style={{
          width: "92%",
          height: "70px",
          background: "#487EEA",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          padding: "0 20px",
          position: "relative",
          zIndex: 1000,
        }}
      >
        {/* اللوجو / الاسم */}
        <div
          style={{
            fontFamily: "Lemonada",
            fontSize: "1.3rem",
            fontWeight: "bold",
            color: "white",
            textShadow: "2px 2px 4px rgba(0,0,0,0.5)",
          }}
        >
          Mr.Ashraf Abed
        </div>

        {/* زرار المنيو (هامبورجر) */}
        <button
          onClick={() => setMenuOpen(true)}
          style={{
            background: "transparent",
            border: "none",
            color: "white",
            fontSize: "2rem",
            cursor: "pointer",
          }}
        >
          ☰
        </button>
      </header>

      {/* ======= القائمة الجانبية ======= */}
      <div
        style={{
          position: "fixed",
          top: 0,
          right: menuOpen ? 0 : "-250px", // slide effect
          width: "200px",
          height: "100%",
          background: "rgba(72,126,234,0.95)", // شفاف شوية
          backdropFilter: "blur(6px)",
          boxShadow: "-2px 0 10px rgba(0,0,0,0.3)",
          transition: "right 0.3s ease-in-out",
          zIndex: 2000,
          display: "flex",
          flexDirection: "column",
          padding: "20px",
          gap: "15px",
        }}
      >
        {/* زرار X (إغلاق) */}
        <button
          onClick={() => setMenuOpen(false)}
          style={{
            alignSelf: "flex-end",
            background: "transparent",
            border: "none",
            fontSize: "1.8rem",
            color: "white",
            cursor: "pointer",
            marginBottom: "10px",
          }}
        >
          ✖
        </button>

        {/* زرارين الدخول / إنشاء حساب */}
        <button style={styles.menuButton2} onClick={handleLogin}>
          تسجيل الدخول
        </button>
        <button style={styles.menuButton1} onClick={handleCreateAccount}>
          انشئ حسابك
        </button>

        {/* روابط القائمة */}
        <button style={styles.menuButton} onClick={() => scrollToSection("home")}>
          الرئيسية
        </button>
        <button style={styles.menuButton} onClick={() => scrollToSection("about")}>
          نظام الحصص
        </button>
        <button style={styles.menuButton} onClick={() => navigate("/pricingCard")}>
          الحصص الشهرية
        </button>
        <button
          style={styles.menuButton}
          onClick={() => {
            const token = localStorage.getItem("authToken");
            const lessonId = localStorage.getItem("lesson_id");
            if (token && lessonId) {
              navigate("/ProfileCard");
            } else {
              navigate("/Login");
            }
          }}
        >
          المحاضرات
        </button>

        {/* أيقونات السوشيال ميديا */}
        <div
          style={{
            display: "flex",
            gap: "15px",
            marginTop: "auto",
            justifyContent: "center",
          }}
        >
          <a
            href="https://www.facebook.com/AshrafAbed2020/photos"
            target="_blank"
            rel="noopener noreferrer"
          >
            <img src={web} alt="Facebook" style={styles.icon} />
          </a>
          <a
            href="https://www.youtube.com/channel/UC2_e1-9trV5x3beP_wXQfpw"
            target="_blank"
            rel="noopener noreferrer"
          >
            <img src={youtube2} alt="YouTube" style={styles.icon} />
          </a>
        </div>
      </div>
    </>
  );
}

export default Header;

const styles = {
  menuButton: {
    padding: "0.7em 1.5em",
    borderRadius: "25px",
    fontSize: "1.1em",
    cursor: "pointer",
    background: "#fff",
    color: "#487EEA",
    border: "none",
    transition: "all 0.3s ease",
    textAlign: "center",
  },
  menuButton1: {
    padding: "0.7em 1.5em",
    borderRadius: "25px",
    fontSize: "1.1em",
    cursor: "pointer",
    background: "#487EEA",
    color: "white",
    border: "none",
    transition: "all 0.3s ease",
  },
  menuButton2: {
    padding: "0.7em 1.5em",
    borderRadius: "25px",
    fontSize: "1.1em",
    cursor: "pointer",
    background: "#487EEA",
    color: "white",
    border: "none",
    transition: "all 0.3s ease",
  },
  icon: {
    width: "40px",
    height: "40px",
    borderRadius: "6px",
    background: "white",
    padding: "5px",
    boxShadow: "0 2px 5px rgba(0,0,0,0.2)",
  },
};
