import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

import "./video.css";
import Footer from "./Footer";
import ChatComponent from "./ChatComponent";
import Bubbles from "../Bubbles";

// 🔹 Resource Button
const ResourceButton = ({ label, href, onClick }) => (
  <a
    className="resource-btn"
    href={href}
    onClick={onClick}
  >
    {label}
  </a>
);

// 🔹 Video Player
const VideoPlayer = ({ url }) => (
  <div className="video-container animiT">
    {url ? (
      <iframe
        title="Video"
        src={url}
        width="100%"
        height="100%"
        frameBorder="0"
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
        referrerPolicy="strict-origin-when-cross-origin"
        allowFullScreen
      />
    ) : (
      <p>Loading video...</p>
    )}
  </div>
);

export default function Video() {
  const [videoData, setVideoData] = useState({
    url: "",
    title: "",
    description: "",
  });
  const [quizUrl, setQuizUrl] = useState("");
  const [menuOpen, setMenuOpen] = useState(false);

  const navigate = useNavigate();

  // 🔹 Fetch video + quiz
  useEffect(() => {
    const fetchData = async () => {
      try {
        const token = localStorage.getItem("authToken");
        const lessonId = localStorage.getItem("lesson_id") || 2;

        const headers = { Authorization: `Bearer ${token}` };

        const videoRes = await fetch(
          `${process.env.REACT_APP_API_BASE_URL}/videos/lesson/${lessonId}`,
          { headers }
        );
        const videoJson = await videoRes.json();

        if (videoJson?.length > 0) {
          setVideoData({
            url: videoJson[0].url,
            title: videoJson[0].title,
            description: videoJson[0].description,
          });
        }

        const quizRes = await fetch(
          `${process.env.REACT_APP_API_BASE_URL}/mcqs/lesson/${lessonId}`,
          { headers }
        );
        const quizJson = await quizRes.json();

        if (quizJson?.mcqs?.length > 0) {
          setQuizUrl(quizJson.mcqs[0].url);
        }
      } catch (err) {
        console.error("❌ Error fetching data:", err);
      }
    };

    fetchData();
  }, []);

  // 🔹 Logout function
  const handleLogout = async () => {
    const token = localStorage.getItem("authToken");
    if (!token) return;

    try {
      await axios.post(
        `${process.env.REACT_APP_API_BASE_URL}/logout`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );

      localStorage.clear();
      navigate("/Login");
    } catch (error) {
      console.error("Logout Failed:", error);
    }
  };

  return (
    <div className="landing-page-wrapper">
      {/* خلفية Bubbles */}
      <div className="background-bubbles">
        <Bubbles />
      </div>

      {/* ======= Header ======= */}
      <header className="profile-header glassy-nav">
        <div className="profile-header-content">
          <div className="profile-name animiR">Mr.Ashraf Abed</div>
          <button
            className="menu-toggle"
            onClick={() => setMenuOpen(!menuOpen)}
          >
            ☰
          </button>
        </div>
      </header>

      {/* ======= Side Menu ======= */}
      <nav className={`side-menu ${menuOpen ? "open" : ""}`}>
        <button className="close-btn" onClick={() => setMenuOpen(false)}>
          ✕
        </button>
        <button className="menu-btn" onClick={() => navigate("/")}>
          الرئيسية
        </button>
        <button className="menu-btn" onClick={() => navigate("/about")}>
          عن المنصة
        </button>
        <button className="menu-btn" onClick={() => navigate("/PricingCard")}>
          الحصص الشهرية
        </button>
        <button className="menu-btn" onClick={() => navigate("/ProfileCard")}>
          المحاضرات
        </button>
        <button className="menu-btn logout" onClick={handleLogout}>
          تسجيل الخروج
        </button>
      </nav>

      {/* ======= Video Section ======= */}
      <div className="page-container">
        <section className="video-section card">
          <VideoPlayer url={videoData.url} />
        </section>
      </div>

      {/* ======= Video details ======= */}
      <div className="video-details animiR">
        <h2>{videoData.title}</h2>
        <p>{videoData.description}</p>

        <div className="resources">
          <ResourceButton label="الواجب" href="/AssignmentsPage" />
          <ResourceButton label="الملازم" href="/PdfList" />
          <ResourceButton
            label="Quiz"
            href={quizUrl || "#"}
            onClick={() => !quizUrl && alert("لم يتم تنزيل امتحان")}
          />
        </div>
      </div>

      {/* Chat + Footer */}
      <ChatComponent />
      <Footer />
    </div>
  );
}
